code='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    def runs(length, occupied):
        spans = []
        i = 0
        while i < length:
            if not occupied(i):
                i += 1
                continue
            start = i
            while i < length and occupied(i):
                i += 1
            spans.append((start, i))
        if not spans:
            return []
        sizes = [end - start for start, end in spans]
        common_size = max(set(sizes), key=sizes.count)
        return [(start, end) for start, end in spans if end - start == common_size]

    row_bands = runs(h, lambda r: any(v != 0 for v in grid[r]))
    col_bands = runs(w, lambda c: any(grid[r][c] != 0 for r in range(h)))
    if not row_bands or not col_bands:
        return out
    centers_r = [(a + b - 1) // 2 for a, b in row_bands]
    centers_c = [(a + b - 1) // 2 for a, b in col_bands]
    values = [[grid[r][c] for c in centers_c] for r in centers_r]
    counts = {}
    for row in values:
        for color in row:
            counts[color] = counts.get(color, 0) + 1
    if not counts:
        return out
    common = max(counts, key=counts.get)
    colors = [color for color in counts if color != common and color != 0]

    for color in colors:
        for ri, row in enumerate(values):
            cols = [centers_c[ci] for ci, value in enumerate(row) if value == color]
            if len(cols) >= 2:
                r = centers_r[ri]
                for c in range(min(cols), max(cols) + 1):
                    if grid[r][c] == 0:
                        out[r][c] = color
        for ci in range(len(centers_c)):
            rows = [centers_r[ri] for ri, row in enumerate(values) if row[ci] == color]
            if len(rows) >= 2:
                c = centers_c[ci]
                for r in range(min(rows), max(rows) + 1):
                    if grid[r][c] == 0:
                        out[r][c] = color
    return out
