code='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    def bands(length, occupied):
        spans = []
        i = 0
        while i < length:
            if not occupied(i):
                i += 1
                continue
            start = i
            while i < length and occupied(i):
                i += 1
            spans.append((start, i))
        if not spans:
            return []
        sizes = [b - a for a, b in spans]
        nominal = max(set(sizes), key=sizes.count)
        kept = [(a, b, nominal) for a, b in spans if b - a == nominal]
        if spans and spans[-1][1] == length and spans[-1][1] - spans[-1][0] != nominal and spans[-1][1] - spans[-1][0] >= 2:
            kept.append((spans[-1][0], spans[-1][1], nominal))
        return kept

    rb = bands(h, lambda r: any(v != 0 for v in grid[r]))
    cb = bands(w, lambda c: any(grid[r][c] != 0 for r in range(h)))
    if not rb or not cb:
        return out

    patches, counts = {}, {}
    for ri, (ra, rz, rh) in enumerate(rb):
        for ci, (ca, cz, cw) in enumerate(cb):
            rfull, cfull = rz - ra == rh, cz - ca == cw
            # Test only sides that are known to be tile borders; a clipped edge may cut through the core.
            perimeter = [grid[ra][c] for c in range(ca, min(cz, ca + cw))]
            perimeter += [grid[r][ca] for r in range(ra, min(rz, ra + rh))]
            if rfull:
                perimeter += [grid[rz-1][c] for c in range(ca, min(cz, ca + cw))]
            if cfull:
                perimeter += [grid[r][cz-1] for r in range(ra, min(rz, ra + rh))]
            framed = bool(perimeter) and perimeter[0] != 0 and all(v == perimeter[0] for v in perimeter)
            if framed:
                ya, yb = ra + 1, min(rz, ra + rh - 1)
                xa, xb = ca + 1, min(cz, ca + cw - 1)
            else:
                ya, yb, xa, xb = ra, rz, ca, cz
            cells = {}
            for r in range(ya, yb):
                for c in range(xa, xb):
                    color = grid[r][c]
                    if color:
                        cells.setdefault(color, []).append((r, c))
                        counts[color] = counts.get(color, 0) + 1
            patches[(ri, ci)] = cells
    if not counts:
        return out
    common_color = max(counts, key=counts.get)

    boxes = {}
    for (ri, ci), cells_by_color in patches.items():
        for color, cells in cells_by_color.items():
            if color != common_color:
                boxes[(ri, ci, color)] = (min(r for r,c in cells), max(r for r,c in cells),
                                          min(c for r,c in cells), max(c for r,c in cells))

    for (ri, ci, color), (y1, y2, x1, x2) in list(boxes.items()):
        for cj in range(ci + 1, len(cb)):
            other = boxes.get((ri, cj, color))
            if other is not None:
                oy1, oy2, ox1, ox2 = other
                for r in range(max(y1, oy1), min(y2, oy2) + 1):
                    for c in range(x2 + 1, ox1):
                        if grid[r][c] == 0:
                            out[r][c] = color
                break
        for rj in range(ri + 1, len(rb)):
            other = boxes.get((rj, ci, color))
            if other is not None:
                oy1, oy2, ox1, ox2 = other
                for c in range(max(x1, ox1), min(x2, ox2) + 1):
                    for r in range(y2 + 1, oy1):
                        if grid[r][c] == 0:
                            out[r][c] = color
                break
    return out
